# Cemetery Recruitment (FDN).
# "Return target creature card from your graveyard to your hand." -- M20 Disentomb's verified
#   record, word for word.
# "If it's a Zombie card, draw a card." -- M21 Track Down's B5b-if-it-type-then Conditional (judged
#   on "it", the card the move just acted on: the result register), SUBTYPE_EQ Zombie.
abilities = [
    SpellAbility(
        kind=SpellKind.SORCERY,
        effect=Seq(
            steps=(
                A(Verb.MOVE_ZONE, {
                    'cards': Selector(
                        count=QConst(value=1),
                        mode=SelectorMode.TARGET,
                        filter=FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                        zones=(Zone(kind=ZoneKind.GRAVEYARD, controller=ControllerRef.YOU),),
                    ),
                    'destination': Zone(kind=ZoneKind.HAND, controller=ControllerRef.YOU),
                }),
                Conditional(
                    pred=FAtom(pred=FAtomPred.SUBTYPE_EQ, string_value='Zombie'),
                    then_effect=A(Verb.DRAW, {
                        'amount': QConst(value=1),
                        'controller': ControllerRef.YOU,
                    }),
                ),
            ),
        ),
    ),
]
